{
  "name": "autocad-skill",
  "version": "0.5.0",
  "description": "Installer, updater, and doctor for the Engineering CAD Agent Skill (OpenCode). Copies plain Markdown/JSON skill files into place; never bundles autocad-mcp.",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/salahkhafaga1/AutoCAD-Skill.git"
  },
  "homepage": "https://github.com/salahkhafaga1/AutoCAD-Skill#readme",
  "bugs": {
    "url": "https://github.com/salahkhafaga1/AutoCAD-Skill/issues"
  },
  "bin": {
    "autocad-skill": "bin/autocad-skill.js"
  },
  "files": [
    "bin",
    "lib",
    "skill",
    "tools",
    "README.md",
    "CHANGELOG.md",
    "LICENSE"
  ],
  "scripts": {
    "prepack": "node scripts/prepack.js",
    "test": "node --test test/"
  },
  "engines": {
    "node": ">=18"
  },
  "keywords": [
    "autocad",
    "cad",
    "opencode",
    "skill",
    "agent",
    "mcp",
    "installer"
  ]
}
